// Replay test for batch257 — lineHeights.ts.
// Truth generated by tool/ts2dart/_batch257_truth.cjs (real recursive TS transpile).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../lib/src/monaco/editor/common/config/editorConfiguration.dart';
import '../lib/src/monaco/editor/common/config/editorOptions.dart';
import '../lib/src/monaco/editor/common/core/position.dart';
import '../lib/src/monaco/editor/common/core/range.dart';
import '../lib/src/monaco/editor/common/coordinatesConverter.dart';
import '../lib/src/monaco/editor/common/viewLayout/lineHeights.dart';

Map<String, dynamic> _loadTruth() => jsonDecode(
      File('tool/ts2dart/batch257_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

void main() {
  final truth = _loadTruth();

  group('batch257 lineHeights replay', () {
    test('all source-test cases (38 cases, 159 reads)', () {
      for (final c in (truth['cases'] as List).cast<Map<String, dynamic>>()) {
        final label = c['label'] as String;
        final initial = (c['initialData'] as List).cast<Map<String, dynamic>>();
        final manager = LineHeightsManager(
          c['defaultHeight'] as num,
          initial
              .map((d) => CustomLineHeightData(
                    d['decorationId'] as String,
                    (d['startLineNumber'] as num).toInt(),
                    (d['endLineNumber'] as num).toInt(),
                    d['lineHeight'] as num,
                  ))
              .toList(),
        );

        // Read expectations are stored separately in `outputs` in order.
        final outputs = (c['outputs'] as List).cast<Map<String, dynamic>>();
        int readIndex = 0;
        for (final op in (c['ops'] as List)) {
          final parts = (op as List).cast<dynamic>();
          switch (parts[0] as String) {
            case 'set':
              manager.defaultLineHeight = parts[1] as num;
              break;
            case 'ins':
              manager.insertOrChangeCustomLineHeight(
                parts[1] as String,
                (parts[2] as num).toInt(),
                (parts[3] as num).toInt(),
                parts[4] as num,
              );
              break;
            case 'rm':
              manager.removeCustomLineHeight(parts[1] as String);
              break;
            case 'del':
              manager.onLinesDeleted(
                (parts[1] as num).toInt(),
                (parts[2] as num).toInt(),
              );
              break;
            case 'add':
              manager.onLinesInserted(
                (parts[1] as num).toInt(),
                (parts[2] as num).toInt(),
              );
              break;
            case 'rh': {
              final out = outputs[readIndex++];
              expect(out['kind'], 'h');
              expect(out['line'], parts[1]);
              final expected = (out['value'] as num).toInt();
              expect(manager.heightForLineNumber((parts[1] as num).toInt()),
                  expected,
                  reason: '[$label] heightForLineNumber(${parts[1]})');
              break;
            }
            case 'ra': {
              final out = outputs[readIndex++];
              expect(out['kind'], 'acc');
              expect(out['line'], parts[1]);
              final expected = (out['value'] as num).toInt();
              expect(
                  manager.getAccumulatedLineHeightsIncludingLineNumber(
                      (parts[1] as num).toInt()),
                  expected,
                  reason: '[$label] accumulated(${parts[1]})');
              break;
            }
            default:
              fail('[$label] unknown op ${parts[0]}');
          }
        }

        // Every recorded TS read must have been replayed.
        expect(readIndex, outputs.length,
            reason: '[$label] read count mismatch');
      }
    });

    test('fromDecorations maps decorations to view ranges', () {
      final expected = (truth['fromDecorations'] as List).cast<Map<String, dynamic>>();
      final config = _ConfigMock();
      final coords = IdentityCoordinatesConverter(_ModelMock());
      final decorations = <IModelDecorationForLineHeight>[
        IModelDecorationForLineHeight(
          'd1',
          Range(2, 1, 4, 5),
          IModelDecorationOptionsForLineHeight(2),
        ),
        IModelDecorationForLineHeight(
          'd2',
          Range(6, 1, 6, 9),
          IModelDecorationOptionsForLineHeight(null),
        ),
        IModelDecorationForLineHeight(
          'd3',
          Range(8, 1, 8, 2),
          IModelDecorationOptionsForLineHeight(1.5),
        ),
      ];
      final actual = CustomLineHeightData.fromDecorations(decorations, coords, config);
      expect(actual.length, expected.length);
      for (int i = 0; i < expected.length; i++) {
        expect(actual[i].decorationId, expected[i]['decorationId']);
        expect(actual[i].startLineNumber, expected[i]['startLineNumber']);
        expect(actual[i].endLineNumber, expected[i]['endLineNumber']);
        expect(actual[i].lineHeight, expected[i]['lineHeight']);
      }
    });
  });
}

/// Minimal IComputedEditorOptions: only `get(EditorOption.lineHeight)` is read.
class _ComputedOptionsMock implements IComputedEditorOptions {
  @override
  Object? get(Object id) => 20; // default line height used by fromDecorations truth
}

/// Minimal IEditorConfiguration exposing only `options`; other members throw.
class _ConfigMock implements IEditorConfiguration {
  @override
  IComputedEditorOptions get options => _ComputedOptionsMock();

  @override
  bool get isSimpleWidget => false;

  @override
  void dispose() {}

  @override
  dynamic noSuchMethod(Invocation invocation) =>
      throw UnsupportedError('unexpected member: ${invocation.memberName}');
}

/// Minimal model for IdentityCoordinatesConverter (identity validate + lineCount).
class _ModelMock implements ITextModelForCoordinatesConverter {
  @override
  Position validatePosition(Position pos) => pos;

  @override
  Range validateRange(Range range) => range;

  @override
  int getLineCount() => 100;
}
